-- Identity mirror ---------------------------------------------------------------
-- core.students.user_account_id and core.employees.user_id point at this
-- database's identity.users, not the control plane's. The ids match the control
-- rows exactly, so the two sides describe one person. No password lives here --
-- authentication only ever reads the control plane.
INSERT INTO identity.users (id, email, password_hash, display_name, initials,
        account_type, active, profile)
VALUES ('de5b9bb4-694b-50c2-b6da-bdd95a5f1399'::uuid, 'student001@mec.local', 'seeded-in-control-plane', 'Priya Kumar', 'PK', 'student', true, '{"gender": "female", "residency": "hosteller", "dept": "AIDS", "roll": "MEC26AI001", "year": "I", "team": "Students", "section": "A", "hostel": "Girls Hostel", "room": "GH-101"}'::jsonb)
ON CONFLICT (email) DO UPDATE SET
    display_name = EXCLUDED.display_name, initials = EXCLUDED.initials,
    account_type = EXCLUDED.account_type, active = true, profile = EXCLUDED.profile;
INSERT INTO identity.users (id, email, password_hash, display_name, initials,
        account_type, active, profile)
VALUES ('a50bea62-952e-5213-a6b6-0a5a01a15c4d'::uuid, 'student002@mec.local', 'seeded-in-control-plane', 'Vignesh Kumar', 'VK', 'student', true, '{"gender": "male", "residency": "hosteller", "dept": "AIDS", "roll": "MEC26AI002", "year": "I", "team": "Students", "section": "A", "hostel": "Boys Hostel", "room": "BH-101"}'::jsonb)
ON CONFLICT (email) DO UPDATE SET
